const writebackUnitCost = `-- name: WritebackUnitCost :exec
UPDATE inventory_transactions SET unit_cost = $1
WHERE company_id = $2 AND item_id = $3
  AND doc_date BETWEEN $4::date AND $5::date
  AND source_type NOT IN ('goods_receipt', 'purchase_return', 'opening_stock', 'work_order_receipt', 'wo_completion_receipt')
`

type WritebackUnitCostParams struct {
	AvgCost   *decimal.Decimal
	CompanyID int64
	ItemID    int64
	StartDate time.Time
	EndDate   time.Time
}

// 把平均成本回寫到沒有成本的流水帳(出貨、銷貨退回、調整、盤點、調撥);進貨的單位成本保留原值
func (q *Queries) WritebackUnitCost(ctx context.Context, arg WritebackUnitCostParams) error {
	_, err := q.db.Exec(ctx, writebackUnitCost,
		arg.AvgCost,
		arg.CompanyID,
		arg.ItemID,
		arg.StartDate,
		arg.EndDate,
	)
	return err
}
